{
  "query": "{ __type(name: \"ReservationDailyStatisticsDetailsType\") { fields { name type { name kind ofType { name } } } } }"
}

{
  "query": "query FinancialTransactionDetails($input: FinancialTransactionDetailsQueryArgumentsType!) {
  financialTransactionDetails(input: $input) {
    financialTransactionDetails {
      businessDate
      resort
      resvNameId
      originalResvNameId
      rateCode
      sourceCode
      ftSubtype
      tcGroup
      tcSubgroup
      trxCode
      trxDate
      netAmount
      grossAmount
      trxAmount
      postedAmount
      quantity
      pricePerUnit
      revenueAmt
      passerByName
      trxNoAddedBy
      trxNo
      tranActionId
      marketCode
      exchangeRate
      currencyCode
      indRevenueGp
    }
  }
}",
  "variables": {
    "input": {
      "financialTransactionDetailsResort": { "_in": ["{{hotelCode}}"] },
      "financialTransactionDetailsBusinessDate": {
        "_gte": "{{startDate}}",
        "_lte": "{{endDate}}"
      }
    }
  }
}

{
  "query": "{ __type(name: \"FinancialTransactionDetailsType\") { fields { name type { name kind ofType { name } } } } }"
}

{
  "query": "query StatisticsReservationPace($input: StatisticsReservationPaceQueryArgumentsType!) {
  statisticsReservationPace(input: $input) {
    reservationPaceFactDetails {
      resort
      snapshotDate
      stayDate
      marketCode
      roomCategoryLabel
      channel
      rateCode
      roomsOnBooks
      revenueOnBooks
    }
  }
}",
  "variables": {
    "input": {
      "reservationPaceFactDetailsResort": { "_in": ["{{hotelCode}}"] },
      "reservationPaceFactDetailsSnapshotDate": { "_eq": "{{startDate}}" },
      "reservationPaceFactDetailsStayDate": {
        "_gte": "{{otbStartDate}}",
        "_lte": "{{otbEndDate}}"
      }
    }
  }
}

{
  "query": "{ __type(name: \"ForecastSummaryDetailsType\") { fields { name type { name kind ofType { name } } } } }"
}

{
  "query": "query FinancialTransactionCodes($input: FinancialTransactionCodesQueryArgumentsType!) {
  financialTransactionCodes(input: $input) {
    transactionCodeDetails {
      resort
      trxCode
      description
      trxGroup
      trxSubgroup
      revenueYn
      roomRevenueYn
      packageYn
      activeYn
    }
  }
}",
  "variables": {
    "input": {
      "transactionCodeDetailsResort": { "_in": ["{{hotelCode}}"] }
    }
  }
}

{
  "query": "query InventoryRooms($input: InventoryRoomsQueryArgumentsType!) {
  inventoryRooms(input: $input) {
    roomDetails {
      resort
      room
      roomCategoryLabel
      roomCategoryDescription
      roomClass
      pseudoRoomYn
      activeYn
    }
  }
}",
  "variables": {
    "input": {
      "roomDetailsResort": { "_in": ["{{hotelCode}}"] }
    }
  }
}

{
  "query": "query RatesCodeDetails($input: RatesCodeDetailsQueryArgumentsType!) {
  ratesCodeDetails(input: $input) {
    rateCodeDetails {
      resort
      rateCode
      rateDescription
      rateCategory
      rateClass
      marketCode
      sourceCode
      activeYn
    }
  }
}",
  "variables": {
    "input": {
      "rateCodeDetailsResort": { "_in": ["{{hotelCode}}"] }
    }
  }
}

{
  "query": "query ExportMappings($input: ExportMappingsQueryArgumentsType!) {
  exportMappings(input: $input) {
    exportMappingDetails {
      resort
      fieldName
      externalCode
      externalDescription
      activeYn
    }
  }
}",
  "variables": {
    "input": {
      "exportMappingDetailsResort": { "_in": ["{{hotelCode}}"] },
      "exportMappingDetailsFieldName": { "_in": ["MARKETCODE", "SOURCE_CODE", "CHANNEL"] }
    }
  }
}

{
  "query": "query InventoryRooms($input: InventoryRoomsQueryArgumentsType!) {
  inventoryRooms(input: $input) {
    roomDetails {
      resort
      room
      roomStatus
      roomCategoryLabel
      roomClass
      pseudoRoomYn
      activeYn
    }
  }
}",
  "variables": {
    "input": {
      "roomDetailsResort": { "_in": ["{{hotelCode}}"] }
    }
  }
}

{
  "query": "query StatisticsManagersReport($input: StatisticsManagersReportQueryArgumentsType!) {
  statisticsManagersReport(input: $input) {
    managersReportDetails {
      resort
      businessDate
      roomClass
      osRooms
      oooRooms
      availRoom
      physicalBeds
      oooBeds
      osBeds
    }
  }
}",
  "variables": {
    "input": {
      "managersReportDetailsResort": { "_in": ["{{hotelCode}}"] },
      "managersReportDetailsBusinessDate": {
        "_gte": "{{startDate}}",
        "_lte": "{{endDate}}"
      }
    }
  }
}

{
  "query": "query InventoryRoomsManagement($input: InventoryRoomsManagementQueryArgumentsType!) {
  inventoryRoomsManagement(input: $input) {
    roomDetails {
      resort
      date
      room
      roomCategoryLabel
      roomStatus
      outOfOrderYn
      outOfServiceYn
      startDate
      endDate
      reason
    }
  }
}",
  "variables": {
    "input": {
      "roomDetailsResort": { "_in": ["{{hotelCode}}"] },
      "roomDetailsDate": {
        "_gte": "{{startDate}}",
        "_lte": "{{endDate}}"
      }
    }
  }
}

{
  "query": "query BookingsBlock($input: BookingsBlockQueryArgumentsType!) {
  bookingsBlock(input: $input) {
    blockDetails {
      resort
      blockCode
      blockName
      marketCode
      roomCategoryLabel
      blockIdDate
      arrivalDate
      departureDate
      cutoffDate
      blockedRooms
      pickedUpRooms
      remainingRooms
      resvStatus
      currencyCode
    }
  }
}",
  "variables": {
    "input": {
      "blockDetailsResort": { "_in": ["{{hotelCode}}"] },
      "blockDetailsArrivalDate": {
        "_gte": "{{otbStartDate}}",
        "_lte": "{{otbEndDate}}"
      }
    }
  }
}

{
  "query": "query ConfigurationResort($input: ConfigurationResortQueryArgumentsType!) {
  configurationResort(input: $input) {
    propertyDetails {
      resort
      resortName
      country
      currencyCode
      timeZone
      chainCode
    }
  }
}",
  "variables": {
    "input": {
      "propertyDetailsResort": { "_in": ["{{hotelCode}}"] }
    }
  }
}
